frappe.ui.form.on('Bag Recipt', {
    refresh: function (frm) {
        // Change the button class to 'btn-primary'
        frm.fields_dict.add_code.$wrapper.find('button').removeClass('btn-default').addClass('btn-primary');

        // Bind the Add Code button click to the function
        frm.fields_dict.add_code.$wrapper.on('click', function () {
            add_to_bag_barcodes(frm);
        });

        // Bind the Enter key press on barcode_scan field to the function
        frm.fields_dict.barcode_scan.$wrapper.on('keydown', function (event) {
            if (event.key === 'Enter') {
                add_to_bag_barcodes(frm);
            }
        });

        // Automatically trigger the function when the value in barcode_scan changes
        frm.fields_dict.barcode_scan.$wrapper.on('change', function () {
            add_to_bag_barcodes(frm);
        });
    }
});

// Function to handle adding a row to the child table
function add_to_bag_barcodes(frm) {
    let barcode = frm.doc.barcode_scan; // Get the value from barcode_scan field

    if (barcode) {
        // Check if the value is in SVG format and extract plain text
        let plain_barcode = barcode.match(/data-barcode-value="([^"]*)"/);
        barcode = plain_barcode ? plain_barcode[1] : barcode;

        // Add a new row to the Bag Barcodes table
        let new_row = frm.add_child('barcodes'); // Use the child table fieldname
        new_row.bag_number = barcode; // Set bag_number field in the child table
        new_row.barcodes = barcode; // Set barcodes field in the child table

        // Refresh the child table to display the new row
        frm.refresh_field('barcodes');

        // Clear the barcode_scan field
        frm.set_value('barcode_scan', '');
    }
}

frappe.ui.form.on('DestinationArticles', {
    refresh: function(frm) {
        // Add Finish button
        frm.add_custom_button(__('Finish'), function() {
            frappe.msgprint(__('Article entry completed for Destination: {0}', [frm.doc.destination]));
        });
    },
    article_number: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.article_number) {
            // Automatically add a new row to the child table
            frm.add_child('articles');
            frm.refresh_field('articles');
        }
    }
});

