// Function to handle adding a row to the child table
function add_to_bag_barcodes(frm) {
    let barcode = frm.doc.barcode_scan; // Get the value from barcode_scan field

    if (barcode) {
        // Check if the barcode already exists in the child table
        let is_duplicate = frm.doc.barcodes.some(row => row.bag_number === barcode);

        if (is_duplicate) {
            // Show an error message if duplicate
            frappe.msgprint(__('Duplicate Bag Number is not allowed: {0}', [barcode]), __('Duplicate Entry'));
        } else {
            // Add a new row to the Bag Barcodes table
            let new_row = frm.add_child('barcodes'); // Use the child table fieldname
            new_row.bag_number = barcode; // Set bag_number field in the child table

            // Refresh the child table to display the new row
            frm.refresh_field('barcodes');

            // Update the total count of scanned articles in real-time
            update_total_scanned_articles(frm);

            // Clear the barcode_scan field
            frm.set_value('barcode_scan', '');
        }
    }
}

// Function to update the total count of scanned articles
function update_total_scanned_articles(frm) {
    let count = frm.doc.barcodes ? frm.doc.barcodes.length : 0; // Count the number of entries in the child table
    frm.set_value('total_scanned_article', count); // Set the count in the total_scanned_article field
}

// Prevent duplicate entries in the child table based on bag_number
frappe.ui.form.on('Bag Barcodes', {
    bag_number: function (frm, cdt, cdn) {
        let child_row = locals[cdt][cdn]; // Get the current row
        let bag_number = child_row.bag_number; // Get the bag number value

        // Check if the bag number already exists in the child table
        let is_duplicate = frm.doc.barcodes.some(row => row.bag_number === bag_number && row.name !== child_row.name);

        if (is_duplicate) {
            // Show an error message if duplicate
            frappe.msgprint(__('Duplicate Bag Number is not allowed: {0}', [bag_number]), __('Duplicate Entry'));

            // Clear the value to avoid saving duplicate
            frappe.model.set_value(cdt, cdn, 'bag_number', null);
        } else {
            // Update the total count of scanned articles in real-time
            update_total_scanned_articles(frm);
        }
    }
});

