// validation for 12 char
frappe.ui.form.on('Bag Barcodes', {
    bag_number: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn]; // Get the current row
        let bag_number = row.bag_number;

        // Regular expression for validation: 2 alphabets, 8 digits, 2 alphabets
        const pattern = /^[A-Z]{2}\d{8}[A-Z]{2}$/;

        if (bag_number && !pattern.test(bag_number)) {
            frappe.msgprint({
                title: __('Validation Error'),
                indicator: 'red',
                message: __('Invalid Article Number: {0}. Format: 2 letters, 8 digits, 2 letters. Scan Again!').format(bag_number)
            });

            // Clear the invalid value
            frappe.model.set_value(cdt, cdn, 'bag_number', '');
        }
    }
});
